const urls = [1,2,3].map(page => `https://federation.ccdi.cancer.gov/api/v1/subject?sex=F&page=${page}&per_page=10`);
const results = [];
for (const url of urls) {
  try {
    const res = await fetch(url, { headers: { accept: 'application/json' } });
    const text = await res.text();
    results.push({ url, ok: res.ok, status: res.status, headers: Object.fromEntries(res.headers.entries()), body: text.slice(0, 12000) });
  } catch (err) {
    results.push({ url, ok: false, error: String(err && err.stack || err) });
  }
}
